-- c016-v001: Chegou e também a Derbe e a Listra. E eis, discípulo certo estava ali, por–nome Timóteo, filho de–mulher judia crente, de–pai porém grego,
-- c016-v002: que era–testemunhado pelos os em Listra e Icônio irmãos.
-- c016-v003: Este quis o Paulo com ele sair, e tendo–tomado, circuncidou ele, por–causa dos judeus os que–estavam nos os lugares aqueles; sabiam pois todos, que grego o pai dele era.
-- c016-v004: Quando e passavam as cidades, entregavam a–eles para–guardarem, os decretos os decididos pelos os apóstolos e presbíteros os em Jerusalém.
-- c016-v005: As de–fato pois igrejas eram–fortalecidas na fé, e abundavam em número cada dia.
-- c016-v006: Passaram e pela Frígia, e a–galática região, tendo–sido–impedidos pelo o Santo Espírito de–falarem a palavra na a Ásia,
-- c016-v007: tendo–vindo e até a Mísia, tentavam para a Bitínia irem; e não permitiu eles o Espírito de–Jesus;
-- c016-v008: tendo–passado e a Mísia, desceram para Trôade.
-- c016-v009: E visão durante a noite a Paulo apareceu: homem macedônio certo estava de–pé, e rogando a–ele, e dizendo, Tendo–passado para Macedônia, ajuda– nos.
-- c016-v010: Quando e a visão viu, imediatamente procuramos sair para Macedônia, concluindo que nos–tinha–chamado a–nós o Deus para–evangelizar a–eles.
-- c016-v011: Tendo–navegado e de Trôade, fomos–em–linha–reta para Samotrácia, no e seguinte–dia, para Neápolis, cidade,
-- c016-v012: e–de–ali para Filipos, que é primeira da parte de–Macedônia cidade, colônia. Estávamos e nesta a cidade cidade permanecendo dias alguns.
-- c016-v013: No então dia dos sábados, saímos fora da porta, ao–longo de–rio, onde supuníamos lugar–de–oração haver, e tendo–nos–sentado, falávamos às que–tinham–se–reunido mulheres.
-- c016-v014: E certa mulher, por–nome Lídia, vendedora–de–púrpura de–cidade de–Tiatira, que–adorava a Deus, ouvia; da–qual o Senhor abriu o coração, para–atender às coisas–faladas pelo o Paulo.
-- c016-v015: Quando e foi–batizada, e a casa dela, rogou, dizendo, Se julgastes– me fiel ao Senhor ser, tendo–entrado na a casa minha, ficai. E constrangeu– nos.
-- c016-v016: Aconteceu e, indo nós para o lugar–de–oração, serva certa, tendo espírito de–Píton, encontrar– nos, a–qual lucro muito dava aos senhores dela adivinhando.
-- c016-v017: Esta, seguindo a Paulo e a–nós clamava, dizendo, Estes os homens servos do Deus do Altíssimo são, os–quais anunciam a–vós caminho de–salvação.
-- c016-v018: Isto e fazia por muitos dias. Tendo–se–perturbado e, Paulo, e tendo–se–voltado ao espírito, disse, Ordeno– te em nome de–Jesus Cristo saíres de ela. E saiu nela a hora.
-- c016-v019: Tendo–visto e os senhores dela, que saiu a esperança do lucro deles, tendo–agarrado o Paulo e o Silas, arrastaram para a praça diante dos governantes;
-- c016-v020: e tendo–trazido eles aos magistrados, disseram, Estes os homens perturbam nossa a cidade, judeus sendo,
-- c016-v021: e anunciam costumes, que não é–lícito a–nós recebermos nem praticarmos, romanos sendo.
-- c016-v022: E levantou–se–juntamente a multidão contra eles, e os magistrados tendo–rasgado deles as vestes, ordenavam baterem–com–varas.
-- c016-v023: Muitos então tendo–dado a–eles golpes, lançaram na prisão, tendo–ordenado ao carcereiro seguramente guardar eles.
-- c016-v024: O–qual ordem tal tendo–recebido, lançou eles na a interior prisão, e os pés prendeu deles no o tronco.
-- c016-v025: Pela e a meia–noite, Paulo e Silas, orando, cantavam–hinos a Deus. Escutavam e eles os prisioneiros.
-- c016-v026: De–repente e terremoto houve grande, de–modo–que abalarem–se os alicerces da prisão. Abriram–se e imediatamente as portas todas, e de–todos as cadeias soltaram–se.
-- c016-v027: Acordado e tendo–se–tornado o carcereiro, e tendo–visto abertas as portas da prisão, tendo–desembainhado a espada, estava–para a–si–mesmo matar, supondo terem–fugido os prisioneiros.
-- c016-v028: Clamou porém o Paulo em–grande voz, dizendo, Nenhum faças a–ti–mesmo mal; todos pois estamos aqui.
-- c016-v029: Tendo–pedido e luzes, saltou–dentro, e trêmulo tendo–se–tornado, caiu–diante de Paulo e de Silas.
-- c016-v030: E tendo–trazido eles fora disse, Senhores, que a–mim é–necessário fazer, para–que seja–salvo?
-- c016-v031: Eles e disseram, Crê no o Senhor Jesus, e serás–salvo, tu e a casa tua.
-- c016-v032: E falaram a–ele a palavra do Senhor, com todos os na a casa dele.
-- c016-v033: E tendo–tomado eles naquela a hora hora da noite, lavou de as feridas; e foi–batizado, ele e os dele todos imediatamente.
-- c016-v034: Tendo–levado então eles para a casa, pôs–diante mesa, e alegrou–se com–toda–a–casa, tendo–crido em Deus.
-- c016-v035: De–dia e tendo–havido, enviaram os magistrados os lictores, dizendo, Solta os homens aqueles.
-- c016-v036: Anunciou e o carcereiro as palavras estas a o Paulo que, Enviaram os magistrados, para–que sejais–soltos. Agora pois tendo–saído, ide em paz.
-- c016-v037: O e Paulo disse a eles, Tendo–açoitado a–nós publicamente sem–julgamento, homens, romanos sendo, lançaram na prisão, e agora secretamente a–nós lançam–fora? Não pois; mas tendo–vindo eles a–nós tirem.
-- c016-v038: Anunciaram e aos magistrados os lictores as palavras estas. Temeram e, tendo–ouvido que romanos são.
-- c016-v039: E tendo–vindo, rogaram a–eles, e tendo–tirado, pediam saírem da a cidade.
-- c016-v040: Tendo–saído e da a prisão, entraram para a Lídia; e tendo–visto, exortaram os irmãos e partiram.

